def solve(kind, message):
    class Email:
        def send(self, text):
            return "email:" + text

    class Sms:
        def send(self, text):
            return "sms:" + text

    registry = {"email": Email, "sms": Sms}
    cls = registry.get(kind)
    if cls is None:
        return "error"
    return cls().send(message)
